+      }
+    }
+    top.push(mTop ? String.fromCodePoint(0x2800 + mTop) : ' ');
+    bottom.push(mBot ? String.fromCodePoint(0x2800 + mBot) : ' ');
+  }
+  return [top.join(''), bottom.join('')];
