+
+function pixelRows(secs: number): string[] {
+  const out: string[] = ['', ''];
+  hmsParts(secs).forEach((part, i) => {
+    for (const ch of part) {
+      const [t, b] = pixToBraille(pixelDigits[ch] ?? ['00000', '00000', '00000', '00000', '00000', '00000', '00000']);
+      out[0] += t + ' ';
+      out[1] += b + ' ';
+    }
+    if (i < 2) {
+      const [t, b] = pixToBraille(pixelDigits[':']);
