let out = '';

out += '\n' + magenta('PUNCH design ideation gallery') + gray('  ·  timer 02:45:00  ·  now 1:33 PM') + '\n';

// ---------- timer text styles ----------

out += section('TIMER TEXT STYLES');

for (const font of FONTS) {
  const desc =
